              ('DN0302', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E20\0E32\0E22\0E43\0E19\0020\0034\0038\0020\0E0A\0E31\0E48\0E27\0E42\0E21\0E07\0020\0E20\0E32\0E22\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0020\0028\0E40\0E09\0E1E\0E32\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E15\0E48\0E2D\0E2A\0E21\0E2D\0E07\0029', 'Head Injury: Percent of mortality within 48 hours'),
              ('DN0302', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E20\0E32\0E22\0E43\0E19\0020\0034\0038\0020\0E0A\0E31\0E48\0E27\0E42\0E21\0E07\0020\0E20\0E32\0E22\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0020\0028\0E40\0E09\0E1E\0E32\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E15\0E48\0E2D\0E2A\0E21\0E2D\0E07\0029', 'Head Injury: Percent of mortality within 48 hours'),
              ('DN0302', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E20\0E32\0E22\0E43\0E19\0020\0034\0038\0020\0E0A\0E31\0E48\0E27\0E42\0E21\0E07\0020\0E20\0E32\0E22\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0020\0028\0E40\0E09\0E1E\0E32\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E15\0E48\0E2D\0E2A\0E21\0E2D\0E07\0029', 'Head Injury: Percent of mortality within 48 hours'),
              ('DN0302', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E20\0E32\0E22\0E43\0E19\0020\0034\0038\0020\0E0A\0E31\0E48\0E27\0E42\0E21\0E07\0020\0E20\0E32\0E22\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0020\0028\0E40\0E09\0E1E\0E32\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E15\0E48\0E2D\0E2A\0E21\0E2D\0E07\0029', 'Head Injury: Percent of mortality within 48 hours'),
