              ('DR0102', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0102', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0102', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0102', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0102', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0102', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0102')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0102
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0103' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND (
                    scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                    OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                    OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                    OR scr.advice7_note ILIKE '%smoke%'
                    OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen_advice adv
                JOIN opdscreen_advice_item itm ON itm.opdscreen_advice_item_id = adv.opdscreen_advice_item_id
                JOIN ovst v ON v.vn = adv.vn
                WHERE v.an = periodized.an
                  AND (
                    itm.opdscreen_advice_item_name ILIKE '%smoke%'
                    OR itm.opdscreen_advice_item_name ILIKE U&'%\0E1A\0E38\0E2B\0E23\0E35\0E48%'
                  )
              )
            )) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND (
                    scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                    OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                    OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                    OR scr.advice7_note ILIKE '%smoke%'
                    OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen_advice adv
                JOIN opdscreen_advice_item itm ON itm.opdscreen_advice_item_id = adv.opdscreen_advice_item_id
                JOIN ovst v ON v.vn = adv.vn
                WHERE v.an = periodized.an
                  AND (
                    itm.opdscreen_advice_item_name ILIKE '%smoke%'
                    OR itm.opdscreen_advice_item_name ILIKE U&'%\0E1A\0E38\0E2B\0E23\0E35\0E48%'
                  )
              )
            ))) * 100 / NULLIF((COUNT(*)), 0), 2) AS value
          FROM periodized
          WHERE (LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')) AND (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND (
                    LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                    OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND scr.smoking_type_id IN (2, 3)
              )
            )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0103', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given'),
              ('DR0103', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Pneumonia: Percent of smoking cessation advice given')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0103')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0103
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0201' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE died) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE died) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE pdx IN ('A15', 'A16')
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0201', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months'),
              ('DR0201', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14\0E43\0E19\0E0A\0E48\0E27\0E07\0020\0031\0032\0020\0E40\0E14\0E37\0E2D\0E19', 'TB: Percent of mortality during 12 months')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0201')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0201
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0202' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT clinicmember_id) FILTER (WHERE tb_scr.flagged) AS numerator,
            COUNT(DISTINCT clinicmember_id) AS denominator,
            ROUND((COUNT(DISTINCT clinicmember_id) FILTER (WHERE tb_scr.flagged) * 100.0) / NULLIF(COUNT(DISTINCT clinicmember_id), 0), 2) AS value
          FROM chronic_periodized
          LEFT JOIN LATERAL (
          SELECT EXISTS (
            SELECT 1
            FROM tb_lab_examination_sputum ts
            WHERE ts.tb_register_id IN (
                SELECT tbrs.tb_register_id FROM tb_register tbrs WHERE tbrs.hn = chronic_periodized.hn
              )
              AND ts.tb_lab_examination_sputum_date >= chronic_periodized.regdate - INTERVAL '12 months'
              AND ts.tb_lab_examination_sputum_date <= chronic_periodized.regdate
          ) OR EXISTS (
            SELECT 1
            FROM clinic_visit cv
            JOIN ovst cvv ON cvv.vn = cv.vn
            WHERE cv.hn = chronic_periodized.hn
              AND cv.afb_check = 'Y'
              AND cvv.vstdate >= chronic_periodized.regdate - INTERVAL '12 months'
              AND cvv.vstdate <= chronic_periodized.regdate
          ) OR EXISTS (
            SELECT 1
            FROM tb_register tbr2
            WHERE tbr2.hn = chronic_periodized.hn
              AND tbr2.tb_register_receive_recomment_tb_date >= chronic_periodized.regdate - INTERVAL '12 months'
              AND tbr2.tb_register_receive_recomment_tb_date <= chronic_periodized.regdate
          ) AS flagged
        ) tb_scr ON TRUE
          WHERE (EXISTS (
          SELECT 1
          FROM arv_tx axh
          WHERE axh.hn = chronic_periodized.hn
        ) OR EXISTS (
          SELECT 1
          FROM ovstdiag sdh
          WHERE sdh.hn = chronic_periodized.hn
            AND (LEFT(REPLACE(UPPER(TRIM(sdh.icd10)), '.', ''), 3) IN ('B20', 'B21', 'B22', 'B23', 'B24') OR REPLACE(UPPER(TRIM(sdh.icd10)), '.', '') IN ('Z21'))
        ))
        AND NOT EXISTS (
          SELECT 1
          FROM tb_register tba
          WHERE tba.hn = chronic_periodized.hn
            AND tba.tb_register_date >= chronic_periodized.regdate - INTERVAL '12 months'
            AND tba.tb_register_date <= chronic_periodized.regdate + INTERVAL '6 months'
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0202', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening'),
              ('DR0202', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0E27\0E31\0E13\0E42\0E23\0E04\0E1B\0E2D\0E14', 'TB: Percentage of people living with HIV having a TB screening')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0202')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0202
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0203' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT clinicmember_id) FILTER (WHERE tdt.tb_discharge_type_name ILIKE U&'%\0E2B\0E32\0E22%' OR tdt.tb_discharge_type_name ILIKE U&'%\0E04\0E23\0E1A%' OR tdt.tb_discharge_type_name ILIKE '%cure%' OR tdt.tb_discharge_type_name ILIKE '%complete%') AS numerator,
            COUNT(DISTINCT clinicmember_id) AS denominator,
            ROUND((COUNT(DISTINCT clinicmember_id) FILTER (WHERE tdt.tb_discharge_type_name ILIKE U&'%\0E2B\0E32\0E22%' OR tdt.tb_discharge_type_name ILIKE U&'%\0E04\0E23\0E1A%' OR tdt.tb_discharge_type_name ILIKE '%cure%' OR tdt.tb_discharge_type_name ILIKE '%complete%') * 100.0) / NULLIF(COUNT(DISTINCT clinicmember_id), 0), 2) AS value
          FROM chronic_periodized
          LEFT JOIN LATERAL (
          SELECT
            tbr.tb_register_id,
            tbr.tb_register_date,
            tbr.tb_register_start_date_treatment,
            tbr.tb_discharge_type_id,
            tbr.clinicmember_tb_patient_type_id,
            tbr.tb_result_sputum_id,
            tbr.tb_register_receive_recomment_hiv_date
          FROM tb_register tbr
          WHERE tbr.hn = chronic_periodized.hn
            AND tbr.tb_register_date >= chronic_periodized.regdate - INTERVAL '3 months'
            AND tbr.tb_register_date <= chronic_periodized.regdate + INTERVAL '3 months'
          ORDER BY ABS(tbr.tb_register_date - chronic_periodized.regdate)
          LIMIT 1
        ) tbr ON TRUE
        LEFT JOIN clinicmember_tb_patient_type tpt
          ON tpt.clinicmember_tb_patient_type_id = tbr.clinicmember_tb_patient_type_id
        LEFT JOIN tb_result_sputum trs
          ON trs.tb_result_sputum_id = tbr.tb_result_sputum_id
        LEFT JOIN tb_discharge_type tdt
          ON tdt.tb_discharge_type_id = tbr.tb_discharge_type_id
          WHERE tbr.tb_register_id IS NOT NULL
        AND (tpt.clinicmember_tb_patient_type_name ILIKE U&'%\0E43\0E2B\0E21\0E48%' OR tpt.clinicmember_tb_patient_type_name ILIKE '%new%')
        AND (trs.tb_result_sputum_name ILIKE U&'%\0E1A\0E27\0E01%' OR trs.tb_result_sputum_name ILIKE '%pos%')
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0203', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success'),
              ('DR0203', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E2A\0E33\0E40\0E23\0E47\0E08\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E27\0E31\0E13\0E42\0E23\0E04', 'TB: Percent of treatment success')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0203')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0203
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0204' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT clinicmember_id) FILTER (WHERE hiv_scr.flagged) AS numerator,
            COUNT(DISTINCT clinicmember_id) AS denominator,
            ROUND((COUNT(DISTINCT clinicmember_id) FILTER (WHERE hiv_scr.flagged) * 100.0) / NULLIF(COUNT(DISTINCT clinicmember_id), 0), 2) AS value
          FROM chronic_periodized
          LEFT JOIN LATERAL (
          SELECT
            tbr.tb_register_id,
            tbr.tb_register_date,
            tbr.tb_register_start_date_treatment,
            tbr.tb_discharge_type_id,
            tbr.clinicmember_tb_patient_type_id,
            tbr.tb_result_sputum_id,
            tbr.tb_register_receive_recomment_hiv_date
          FROM tb_register tbr
          WHERE tbr.hn = chronic_periodized.hn
            AND tbr.tb_register_date >= chronic_periodized.regdate - INTERVAL '3 months'
            AND tbr.tb_register_date <= chronic_periodized.regdate + INTERVAL '3 months'
          ORDER BY ABS(tbr.tb_register_date - chronic_periodized.regdate)
          LIMIT 1
        ) tbr ON TRUE
        LEFT JOIN clinicmember_tb_patient_type tpt
          ON tpt.clinicmember_tb_patient_type_id = tbr.clinicmember_tb_patient_type_id
        LEFT JOIN tb_result_sputum trs
          ON trs.tb_result_sputum_id = tbr.tb_result_sputum_id
        LEFT JOIN tb_discharge_type tdt
          ON tdt.tb_discharge_type_id = tbr.tb_discharge_type_id
        LEFT JOIN LATERAL (
          SELECT
            (tbr.tb_register_receive_recomment_hiv_date IS NOT NULL) OR EXISTS (
              SELECT 1
              FROM lab_head lh
              JOIN lab_order lo ON lo.lab_order_number = lh.lab_order_number
              JOIN lab_items li ON li.lab_items_code = lo.lab_items_code
              WHERE lh.hn = chronic_periodized.hn
                AND (li.lab_items_name ILIKE '%hiv%' OR li.lab_items_name ILIKE U&'%\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35%')
                AND lh.order_date >= chronic_periodized.regdate - INTERVAL '12 months'
                AND lh.order_date <= chronic_periodized.regdate
            ) AS flagged
        ) hiv_scr ON TRUE
          WHERE tbr.tb_register_id IS NOT NULL
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0204', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening'),
              ('DR0204', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E04\0E31\0E14\0E01\0E23\0E2D\0E07\0020\0048\0049\0056', 'TB: Percent of TB having a HIV screening')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0204')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0204
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0205' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT clinicmember_id) FILTER (WHERE art_started.flagged) AS numerator,
            COUNT(DISTINCT clinicmember_id) AS denominator,
            ROUND((COUNT(DISTINCT clinicmember_id) FILTER (WHERE art_started.flagged) * 100.0) / NULLIF(COUNT(DISTINCT clinicmember_id), 0), 2) AS value
          FROM chronic_periodized
          LEFT JOIN LATERAL (
          SELECT
            tbr.tb_register_id,
            tbr.tb_register_date,
            tbr.tb_register_start_date_treatment,
            tbr.tb_discharge_type_id,
            tbr.clinicmember_tb_patient_type_id,
            tbr.tb_result_sputum_id,
            tbr.tb_register_receive_recomment_hiv_date
          FROM tb_register tbr
          WHERE tbr.hn = chronic_periodized.hn
            AND tbr.tb_register_date >= chronic_periodized.regdate - INTERVAL '3 months'
            AND tbr.tb_register_date <= chronic_periodized.regdate + INTERVAL '3 months'
          ORDER BY ABS(tbr.tb_register_date - chronic_periodized.regdate)
          LIMIT 1
        ) tbr ON TRUE
        LEFT JOIN clinicmember_tb_patient_type tpt
          ON tpt.clinicmember_tb_patient_type_id = tbr.clinicmember_tb_patient_type_id
        LEFT JOIN tb_result_sputum trs
          ON trs.tb_result_sputum_id = tbr.tb_result_sputum_id
        LEFT JOIN tb_discharge_type tdt
          ON tdt.tb_discharge_type_id = tbr.tb_discharge_type_id
        LEFT JOIN LATERAL (
          SELECT EXISTS (
            SELECT 1
            FROM arv_tx ax
            WHERE ax.hn = chronic_periodized.hn
              AND ax.date_entry <= chronic_periodized.regdate + INTERVAL '6 months'
          ) AS flagged
        ) art_started ON TRUE
          WHERE tbr.tb_register_id IS NOT NULL
        AND (EXISTS (
          SELECT 1
          FROM arv_tx axh
          WHERE axh.hn = chronic_periodized.hn
        ) OR EXISTS (
          SELECT 1
          FROM ovstdiag sdh
          WHERE sdh.hn = chronic_periodized.hn
            AND (LEFT(REPLACE(UPPER(TRIM(sdh.icd10)), '.', ''), 3) IN ('B20', 'B21', 'B22', 'B23', 'B24') OR REPLACE(UPPER(TRIM(sdh.icd10)), '.', '') IN ('Z21'))
        ))
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0205', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)'),
              ('DR0205', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E27\0E31\0E13\0E42\0E23\0E04\0E17\0E35\0E48\0E21\0E35\0E1C\0E25\0E40\0E25\0E37\0E2D\0E14\0E40\0E2D\0E0A\0E44\0E2D\0E27\0E35\0E1A\0E27\0E01\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E14\0E49\0E27\0E22\0020\0041\006E\0074\0069\0072\0065\0074\0072\006F\0076\0069\0072\0061\006C\0020\0074\0068\0065\0072\0061\0070\0079\0020\0028\0041\0052\0054\0029', 'TB: Percent of HIV-positive TB patients started on Antiretroviral therapy (ART)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0205')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0205
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0301' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) AS numerator,
            COUNT(*) FILTER (WHERE NOT died) AS denominator,
            ROUND((
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) * 100.0) / NULLIF(COUNT(*) FILTER (WHERE NOT died), 0), 2) AS value
          FROM periodized
          WHERE LEFT(pdx, 3) IN ('J45', 'J46')
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0301', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge'),
              ('DR0301', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'Asthma: Percent of unplanned re-admission within 28 days after last discharge')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0301')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0301
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0302' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              UNION
              SELECT 1
              FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND (
                  scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                  OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                  OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                  OR scr.advice7_note ILIKE '%smoke%' OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              UNION
              SELECT 1
              FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND (
                  scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                  OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                  OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                  OR scr.advice7_note ILIKE '%smoke%' OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE 
          LEFT(pdx, 3) IN ('J45', 'J46')
          AND (
            EXISTS (
              SELECT 1 FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND (LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17' OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720')
            )
            OR EXISTS (
              SELECT 1 FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND scr.smoking_type_id IN (2, 3)
            )
          )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0302', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given'),
              ('DR0302', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0041\0073\0074\0068\006D\0061\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', 'Asthma: Percent of smoking cessation advice given')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0302')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0302
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0401' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) AS numerator,
            COUNT(*) FILTER (WHERE NOT died) AS denominator,
            ROUND((
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) * 100.0) / NULLIF(COUNT(*) FILTER (WHERE NOT died), 0), 2) AS value
          FROM periodized
          WHERE age_y >= 18 AND LEFT(pdx, 3) = 'J44'
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0401', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge'),
              ('DR0401', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0043\004F\0050\0044\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19', 'COPD: Percent of unplanned re-admission into the hospital within 28 days after last discharge')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0401')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0401
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0403' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE died) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE died) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE age_y >= 18 AND LEFT(pdx, 3) = 'J44'
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0403', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality'),
              ('DR0403', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E08\0E32\0E01\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07', 'COPD: Percent of mortality')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0403')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0403
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DR0404' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              UNION
              SELECT 1
              FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND (
                  scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                  OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                  OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                  OR scr.advice7_note ILIKE '%smoke%' OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              UNION
              SELECT 1
              FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND (
                  scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                  OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                  OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                  OR scr.advice7_note ILIKE '%smoke%' OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE 
          age_y >= 18 AND LEFT(pdx, 3) = 'J44'
          AND (
            EXISTS (
              SELECT 1 FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND (LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17' OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720')
            )
            OR EXISTS (
              SELECT 1 FROM opdscreen scr
              JOIN ovst v ON v.vn = scr.vn
              WHERE v.an = periodized.an
                AND scr.smoking_type_id IN (2, 3)
            )
          )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DR0404', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking'),
              ('DR0404', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E2D\0E38\0E14\0E01\0E31\0E49\0E19\0E40\0E23\0E37\0E49\0E2D\0E23\0E31\0E07\0E17\0E35\0E48\0E22\0E31\0E07\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'COPD: Percent of patient with ongoing smoking')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DR0404')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DR0404
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'DS0401' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT clinicmember_id) FILTER (WHERE mmt_retained.flagged) AS numerator,
            COUNT(DISTINCT clinicmember_id) AS denominator,
            ROUND((COUNT(DISTINCT clinicmember_id) FILTER (WHERE mmt_retained.flagged) * 100.0) / NULLIF(COUNT(DISTINCT clinicmember_id), 0), 2) AS value
          FROM chronic_periodized
          LEFT JOIN LATERAL (
          SELECT EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.hn = chronic_periodized.hn
              AND (di.name ILIKE '%methadone%')
              AND oi.vstdate >= chronic_periodized.regdate + INTERVAL '11 months'
              AND oi.vstdate <= chronic_periodized.regdate + INTERVAL '15 months'
          ) AS flagged
        ) mmt_retained ON TRUE
          WHERE EXISTS (
          SELECT 1
          FROM opitemrece oi0
          JOIN drugitems di0 ON di0.icode = oi0.icode
          WHERE oi0.hn = chronic_periodized.hn
            AND di0.name ILIKE '%methadone%'
            AND oi0.vstdate >= chronic_periodized.regdate - INTERVAL '3 months'
            AND oi0.vstdate <= chronic_periodized.regdate + INTERVAL '3 months'
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('DS0401', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 2, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 3, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 5, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 6, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 8, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 9, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 11, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program'),
              ('DS0401', 12, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0020\0031\0020\0E1B\0E35\0E14\0E49\0E27\0E22\0E40\0E21\0E17\0E32\0E42\0E14\0E19\0E23\0E30\0E22\0E30\0E22\0E32\0E27\0020\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E2A\0E32\0E23\0E40\0E2A\0E1E\0E15\0E34\0E14\0E43\0E19\0E01\0E25\0E38\0E48\0E21\0020\006F\0070\0069\006F\0069\0064', 'Opioid group: 1 year retention rate of opioid in methadone maintenance program')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DS0401')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_DS0401
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HC0101' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE opd_periodized.enter_er_time IS NOT NULL) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v2.vn)
          FROM ovst v2
          JOIN ovstdiag sd2 ON sd2.vn = v2.vn
          WHERE v2.hn = opd_periodized.hn
            AND v2.vstdate >= (SELECT fy_start FROM thip_params)
            AND v2.vstdate < (SELECT fy_end FROM thip_params)
            AND LEFT(REPLACE(UPPER(TRIM(sd2.icd10)), '.', ''), 3) IN ('J45', 'J46')
        ) >= 2) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE opd_periodized.enter_er_time IS NOT NULL) * 1.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v2.vn)
          FROM ovst v2
          JOIN ovstdiag sd2 ON sd2.vn = v2.vn
          WHERE v2.hn = opd_periodized.hn
            AND v2.vstdate >= (SELECT fy_start FROM thip_params)
            AND v2.vstdate < (SELECT fy_end FROM thip_params)
            AND LEFT(REPLACE(UPPER(TRIM(sd2.icd10)), '.', ''), 3) IN ('J45', 'J46')
        ) >= 2), 0), 2) AS value
          FROM opd_periodized
          WHERE (
          LEFT(pdx, 3) IN ('J45', 'J46')
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J45', 'J46')
          )
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            JOIN ovst v ON v.vn = sd.vn
            WHERE v.hn = opd_periodized.hn
              AND v.vstdate >= (SELECT fy_start FROM thip_params)
              AND v.vstdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J45', 'J46')
          )
          OR EXISTS (
            SELECT 1
            FROM iptdiag idg
            JOIN ipt i ON i.an = idg.an
            WHERE i.hn = opd_periodized.hn
              AND i.dchdate >= (SELECT fy_start FROM thip_params)
              AND i.dchdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) IN ('J45', 'J46')
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HC0101', 1, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 2, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 3, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 4, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 5, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 6, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 7, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 8, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 9, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 10, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 11, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0101', 12, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0041\0073\0074\0068\006D\0061', 'Customer: Asthma patients or their relative(s) who are able to care for the patient''s needs')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HC0101')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            SUM(facts.value) OVER w AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((SUM(facts.value) OVER w) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HC0101
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HC0102' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v3.vn)
          FROM ovst v3
          JOIN er_regist er3 ON er3.vn = v3.vn
          WHERE v3.hn = opd_periodized.hn
            AND v3.vstdate >= (SELECT fy_start FROM thip_params)
            AND v3.vstdate < (SELECT fy_end FROM thip_params)
        ) >= 3) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v4.vn)
          FROM ovst v4
          JOIN ovstdiag sd4 ON sd4.vn = v4.vn
          WHERE v4.hn = opd_periodized.hn
            AND v4.vstdate >= (SELECT fy_start FROM thip_params)
            AND v4.vstdate < (SELECT fy_end FROM thip_params)
            AND LEFT(REPLACE(UPPER(TRIM(sd4.icd10)), '.', ''), 3) = 'J44'
        ) >= 2) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v3.vn)
          FROM ovst v3
          JOIN er_regist er3 ON er3.vn = v3.vn
          WHERE v3.hn = opd_periodized.hn
            AND v3.vstdate >= (SELECT fy_start FROM thip_params)
            AND v3.vstdate < (SELECT fy_end FROM thip_params)
        ) >= 3) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          SELECT COUNT(DISTINCT v4.vn)
          FROM ovst v4
          JOIN ovstdiag sd4 ON sd4.vn = v4.vn
          WHERE v4.hn = opd_periodized.hn
            AND v4.vstdate >= (SELECT fy_start FROM thip_params)
            AND v4.vstdate < (SELECT fy_end FROM thip_params)
            AND LEFT(REPLACE(UPPER(TRIM(sd4.icd10)), '.', ''), 3) = 'J44'
        ) >= 2), 0), 2) AS value
          FROM opd_periodized
          WHERE (
          LEFT(pdx, 3) IN ('J44')
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J44')
          )
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            JOIN ovst v ON v.vn = sd.vn
            WHERE v.hn = opd_periodized.hn
              AND v.vstdate >= (SELECT fy_start FROM thip_params)
              AND v.vstdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J44')
          )
          OR EXISTS (
            SELECT 1
            FROM iptdiag idg
            JOIN ipt i ON i.an = idg.an
            WHERE i.hn = opd_periodized.hn
              AND i.dchdate >= (SELECT fy_start FROM thip_params)
              AND i.dchdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) IN ('J44')
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HC0102', 1, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 2, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 3, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 4, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 5, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 6, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 7, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 8, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 9, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 10, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 11, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs'),
              ('HC0102', 12, U&'\0E04\0E27\0E32\0E21\0E2A\0E32\0E21\0E32\0E23\0E16\0E43\0E19\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E15\0E19\0E40\0E2D\0E07\002F\0020\0E01\0E32\0E23\0E14\0E39\0E41\0E25\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E0D\0E32\0E15\0E34\0E42\0E23\0E04\0020\0043\004F\0050\0044', 'Customer: COPD patients or their relative(s) who are able to care for the patient''s needs')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HC0102')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HC0102
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0101' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.had_checkup) AS numerator,
            COUNT(DISTINCT hr.staff_key) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.had_checkup)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.checkup = '1'
              )) AS had_checkup
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0101', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up'),
              ('HE0101', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E01\0E32\0E23\0E15\0E23\0E27\0E08\0E23\0E48\0E32\0E07\0E01\0E32\0E22\0E1B\0E23\0E30\0E08\0E33\0E1B\0E35', 'Employee: Percent of employee check-up')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0101')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0101
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0102' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.bmi_over) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.bmi_measured) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.bmi_over)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.bmi_measured), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.bmi IS NOT NULL
              )) AS bmi_measured,
              (EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.bmi >= 23
              )) AS bmi_over
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0102', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI'),
              ('HE0102', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E14\0E31\0E0A\0E19\0E35\0E21\0E27\0E25\0E01\0E32\0E22\0020\0028\0042\004D\0049\0029\0020\0E40\0E01\0E34\0E19\0E40\0E01\0E13\0E11\0E4C\0E21\0E32\0E15\0E23\0E10\0E32\0E19', 'Employee: Percent of employee have exceeding BMI')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0102')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0102
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0103' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.smoker) AS numerator,
            COUNT(DISTINCT hr.staff_key) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.smoker)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.smoking_type_id IN (2, 3)
              )) AS smoker
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0103', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky'),
              ('HE0103', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E21\0E35\0E1E\0E24\0E15\0E34\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E2A\0E39\0E1A\0E1A\0E38\0E2B\0E23\0E35\0E48', 'Employee: Percent of employee have behavior-smoky')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0103')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0103
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0104' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_over_male) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_measured_male) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_over_male)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_measured_male), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (COALESCE(sx.emp_sex_name, '') ILIKE U&'%\0E0A\0E32\0E22%' AND EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.waist IS NOT NULL
              )) AS waist_measured_male,
              (COALESCE(sx.emp_sex_name, '') ILIKE U&'%\0E0A\0E32\0E22%' AND EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.waist > 90
              )) AS waist_over_male
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            LEFT JOIN emp_sex sx ON sx.emp_sex_id = e.emp_sex_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0104', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity'),
              ('HE0104', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E0A\0E32\0E22\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (male) obesity')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0104')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0104
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0105' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_over_female) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_measured_female) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_over_female)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.waist_measured_female), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (COALESCE(sx.emp_sex_name, '') ILIKE U&'%\0E2B\0E0D\0E34\0E07%' AND EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.waist IS NOT NULL
              )) AS waist_measured_female,
              (COALESCE(sx.emp_sex_name, '') ILIKE U&'%\0E2B\0E0D\0E34\0E07%' AND EXISTS (
                SELECT 1
                FROM patient pp
                JOIN opdscreen scr ON scr.hn = pp.hn
                WHERE pp.cid = e.emp_cid
                  AND scr.vstdate >= months.work_month
                  AND scr.vstdate < months.work_month + INTERVAL '1 month'
                  AND scr.waist > 80
              )) AS waist_over_female
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            LEFT JOIN emp_sex sx ON sx.emp_sex_id = e.emp_sex_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0105', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity'),
              ('HE0105', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E40\0E1E\0E28\0E2B\0E0D\0E34\0E07\0E21\0E35\0E20\0E32\0E27\0E30\0E2D\0E49\0E27\0E19\0E25\0E07\0E1E\0E38\0E07', 'Employee: Percent of employee (female) obesity')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0105')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0105
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HE0106' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.got_influenza_vaccine) AS numerator,
            COUNT(DISTINCT hr.staff_key) AS denominator,
            ROUND((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.got_influenza_vaccine)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (EXISTS (
                SELECT 1
                FROM patient pp
                JOIN ovst vv ON vv.hn = pp.hn
                JOIN ovst_vaccine ovv ON ovv.vn = vv.vn
                JOIN person_vaccine pv ON pv.person_vaccine_id = ovv.person_vaccine_id
                WHERE pp.cid = e.emp_cid
                  AND vv.vstdate >= months.work_month
                  AND vv.vstdate < months.work_month + INTERVAL '1 month'
                  AND (pv.vaccine_name ILIKE U&'%\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48%' OR pv.vaccine_name ILIKE '%influenza%')
              )) AS got_influenza_vaccine
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

              ('HE0106', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 2, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 3, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 4, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 5, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 6, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 7, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 8, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization'),
              ('HE0106', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E44\0E14\0E49\0E23\0E31\0E1A\0E27\0E31\0E04\0E0B\0E35\0E19\0E44\0E02\0E49\0E2B\0E27\0E31\0E14\0E43\0E2B\0E0D\0E48', 'Employee: Percent of employee received Influenza immunization')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('HE0106')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value,
            SUM(COALESCE(facts.numerator, 0)) OVER w AS cum_numerator,
            SUM(COALESCE(facts.denominator, 0)) OVER w AS cum_denominator,
            CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END AS cum_value,
            t.target_value AS target,
            CASE WHEN facts.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(facts.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND((CASE WHEN SUM(COALESCE(facts.denominator, 0)) OVER w > 0
                 THEN ROUND(SUM(COALESCE(facts.numerator, 0)) OVER w * 100.0
                            / SUM(COALESCE(facts.denominator, 0)) OVER w, 2)
                 ELSE SUM(facts.value) OVER w END) * 100.0 / t.target_value, 2) END AS cum_vs_target_pct,
            CASE WHEN facts.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND facts.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better'
                      AND facts.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND facts.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better'
                      AND facts.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          LEFT JOIN targets t ON t.indicator_code = expected_codes.indicator_code
          WINDOW w AS (ORDER BY fiscal_periods.period_start)
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HE0106
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HH0101.1' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND scr.smoking_type_id IS NOT NULL
          )) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND scr.smoking_type_id IS NOT NULL
          )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn), 0), 2) AS value
          FROM opd_periodized
          WHERE opd_periodized.age_y >= 15
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES

