              ('SS0103', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E08\0E48\0E32\0E22\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E43\0E2B\0E49\0E2B\0E19\0E48\0E27\0E22\0E07\0E32\0E19\0E16\0E39\0E01\0E15\0E49\0E2D\0E07', 'CSSD: Percent of medical supplies which are accurately provided by the CSSD')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
