              ('DM0203', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E40\0E14\0E47\0E01\0E2D\0E2D\0E17\0E34\0E2A\0E15\0E34\0E01\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E23\0E30\0E1A\0E1A\0E01\0E32\0E23\0E28\0E36\0E01\0E29\0E32\0E44\0E14\0E49\0E2D\0E22\0E48\0E32\0E07\0E19\0E49\0E2D\0E22\0020\0031\0020\0E1B\0E35', 'ASD: Percent of children with Autism spectrum disorder (ASD) that are included in educational system for at least 1 year'),
              ('DM0203', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E40\0E14\0E47\0E01\0E2D\0E2D\0E17\0E34\0E2A\0E15\0E34\0E01\0E04\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E23\0E30\0E1A\0E1A\0E01\0E32\0E23\0E28\0E36\0E01\0E29\0E32\0E44\0E14\0E49\0E2D\0E22\0E48\0E32\0E07\0E19\0E49\0E2D\0E22\0020\0031\0020\0E1B\0E35', 'ASD: Percent of children with Autism spectrum disorder (ASD) that are included in educational system for at least 1 year')
          ), fiscal_periods AS (
