              ('DS0101', 9, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E22\0E32\0E40\0E2A\0E1E\0E15\0E34\0E14\0E01\0E25\0E38\0E48\0E21\0020\004D\0065\0074\0068\0061\006D\0070\0068\0065\0074\0061\006D\0069\006E\0065\0020\0E42\0E14\0E22\0E23\0E27\0E21\0E17\0E35\0E48\0E2B\0E22\0E38\0E14\0E40\0E2A\0E1E\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0033\0020\0E40\0E14\0E37\0E2D\0E19', 'Methamphetamine group: 3 months total remission rate'),
              ('DS0101', 10, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E22\0E32\0E40\0E2A\0E1E\0E15\0E34\0E14\0E01\0E25\0E38\0E48\0E21\0020\004D\0065\0074\0068\0061\006D\0070\0068\0065\0074\0061\006D\0069\006E\0065\0020\0E42\0E14\0E22\0E23\0E27\0E21\0E17\0E35\0E48\0E2B\0E22\0E38\0E14\0E40\0E2A\0E1E\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0033\0020\0E40\0E14\0E37\0E2D\0E19', 'Methamphetamine group: 3 months total remission rate'),
              ('DS0101', 11, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E22\0E32\0E40\0E2A\0E1E\0E15\0E34\0E14\0E01\0E25\0E38\0E48\0E21\0020\004D\0065\0074\0068\0061\006D\0070\0068\0065\0074\0061\006D\0069\006E\0065\0020\0E42\0E14\0E22\0E23\0E27\0E21\0E17\0E35\0E48\0E2B\0E22\0E38\0E14\0E40\0E2A\0E1E\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0033\0020\0E40\0E14\0E37\0E2D\0E19', 'Methamphetamine group: 3 months total remission rate'),
              ('DS0101', 12, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E15\0E34\0E14\0E22\0E32\0E40\0E2A\0E1E\0E15\0E34\0E14\0E01\0E25\0E38\0E48\0E21\0020\004D\0065\0074\0068\0061\006D\0070\0068\0065\0074\0061\006D\0069\006E\0065\0020\0E42\0E14\0E22\0E23\0E27\0E21\0E17\0E35\0E48\0E2B\0E22\0E38\0E14\0E40\0E2A\0E1E\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0033\0020\0E40\0E14\0E37\0E2D\0E19', 'Methamphetamine group: 3 months total remission rate')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('DS0101')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
                                     (SELECT fiscal_year FROM thip_params) - 544)
            GROUP BY v.indicator_code
