              ('SF0104', 10, U&'\0E23\0E30\0E22\0E30\0E40\0E27\0E25\0E32\0E16\0E31\0E27\0E40\0E09\0E25\0E35\0E48\0E22\0E43\0E19\0E01\0E32\0E23\0E40\0E23\0E35\0E22\0E01\0E40\0E01\0E47\0E1A\0E25\0E39\0E01\0E2B\0E19\0E35\0E49\0E04\0E48\0E32\0E23\0E31\0E01\0E29\0E32\0E2A\0E38\0E17\0E18\0E34', 'Financial: Day in account receivable (average collection period for account receivables)'),
              ('SF0104', 11, U&'\0E23\0E30\0E22\0E30\0E40\0E27\0E25\0E32\0E16\0E31\0E27\0E40\0E09\0E25\0E35\0E48\0E22\0E43\0E19\0E01\0E32\0E23\0E40\0E23\0E35\0E22\0E01\0E40\0E01\0E47\0E1A\0E25\0E39\0E01\0E2B\0E19\0E35\0E49\0E04\0E48\0E32\0E23\0E31\0E01\0E29\0E32\0E2A\0E38\0E17\0E18\0E34', 'Financial: Day in account receivable (average collection period for account receivables)'),
              ('SF0104', 12, U&'\0E23\0E30\0E22\0E30\0E40\0E27\0E25\0E32\0E16\0E31\0E27\0E40\0E09\0E25\0E35\0E48\0E22\0E43\0E19\0E01\0E32\0E23\0E40\0E23\0E35\0E22\0E01\0E40\0E01\0E47\0E1A\0E25\0E39\0E01\0E2B\0E19\0E35\0E49\0E04\0E48\0E32\0E23\0E31\0E01\0E29\0E32\0E2A\0E38\0E17\0E18\0E34', 'Financial: Day in account receivable (average collection period for account receivables)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          ),
    targets AS (
            SELECT v.indicator_code,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM (VALUES
              ('SF0104')
            ) AS v(indicator_code)
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE(v.indicator_code, '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND m.kpi_moph_year IN ((SELECT fiscal_year FROM thip_params),
                                     (SELECT fiscal_year FROM thip_params) - 543,
